from fastapi import FastAPI, APIRouter

router1 = APIRouter()
router2 = APIRouter()

@router1.get('/path1')
def handler1():
    return {'msg': 'handler1'}

@router2.get('/path2')
def handler2():
    return {'msg': 'handler2'}

router1.include_router(router2)

# In 0.136.3, modifying router.routes affects only APIRoute objects
original_routes = list(router1.routes)
for i, route in enumerate(original_routes):
    # All items should be APIRoute with modifiable attributes
    assert hasattr(route, 'endpoint'), f"Route {i} has no endpoint attribute"
